// Writes ../dates.json: what Date.parse, new Date and JSON.stringify of
// the Node console's JavaScript engine make of texts and JSON values, in
// the time zone America/New_York, for the Go tests of package jsreq.
//
//   cd /repo/web-nodejs && node ../betterdesk-server/console/routes/internal/jsreq/testdata/nodeoracle/dates.js
'use strict';

process.env.TZ = 'America/New_York';

const fs = require('fs');
const path = require('path');

// supported are the forms the port reads. For each the answer has to be
// equal, a time or NaN.
const supported = [
    '2026-11-10T07:32:11Z', '2026-11-10T07:32:11.1Z', '2026-11-10T07:32:11.12Z', '2026-11-10T07:32:11.123Z',
    '2026-11-10T07:32:11.1239Z', '2026-11-10T07:32:11.123456789Z', '2026-11-10T07:32:11.999999999Z',
    '2026-11-10T07:32:11.12345678901234Z', '2026-11-10T07:32Z', '2026-11-10T07:32:11+01:00', '2026-11-10T07:32:11-08:00',
    '2026-11-10T07:32:11+0530', '2026-11-10T07:32:11.5-0030', '2026-11-10T07:32:11+23:59', '2026-11-10T07:32:11+24:00',
    '2026-11-10T07:32:11+01:60', '2026-11-10T07:32:11+1', '2026-11-10T07:32:11+01', '2026-11-10T07:32:11+01:0',
    '2026-11-10T07:32:11', '2026-11-10T07:32:11.5', '2026-11-10T07:32:11.123456', '2026-11-10T07:32', '2026-07-10T07:32:11',
    '2026-07-10T23:59:59.999', '2026-01-01T00:00:00', '2026-11-10', '2026-07-10', '2026-11-10Z', '0001-01-01', '9999-12-31',
    '2026-11-10 07:32:11', '2026-07-10 07:32:11', '2026-11-10 07:32', '2026-11-10 12:12:02', '2026-11-10 00:00:00',
    '2026-11-10 23:59:59', '2026-11-10 07:32:11Z', '2026-11-10 07:32:11+01:00', '2026-11-10 07:32:11-0500',
    '2026-11-10T07:32:11.Z', '2026-11-10T07:32:60Z', '2026-11-10T07:60:00Z', '2026-11-10T24:00:00Z', '2026-11-10T24:00:00.000Z',
    '2026-11-10T24:00:01Z', '2026-11-10T24:01:00Z', '2026-11-10T25:00:00Z', '2026-11-10T24:00:00', '2026-11-10 24:00:00',
    '2026-02-29T00:00:00Z', '2026-02-30T00:00:00Z', '2026-02-31T00:00:00Z', '2026-04-31T12:00:00Z', '2026-11-32T00:00:00Z',
    '2026-11-00T00:00:00Z', '2026-00-10T00:00:00Z', '2026-13-10T00:00:00Z', '2024-02-29T23:59:59.999Z', '0001-01-01T00:00:00Z',
    '0000-01-01T00:00:00Z', '9999-12-31T23:59:59.999Z', '1969-12-31T23:59:59.999Z', '1970-01-01T00:00:00Z', '2026-02-30',
    '2026-13-01', '2026-11-32', '2026-11-10T7:32:11Z', '2026-11-10T07:3:11Z', '2026-11-10T07:32:1Z', '2026-1-10T07:32:11Z',
    '2026-11-1T07:32:11Z', '26-11-10T07:32:11Z', 'unknown', '', ' ', 'Z', 'T', '2026', '2026-11', '2026-11-10T', '2026-11-10T07',
    '2026-11-10T07:32:11 Z', ' 2026-11-10T07:32:11Z', '2026-11-10T07:32:11Z ', '2026-11-10T07:32:11,123Z', '2026-11-10T07:32:11z',
    '2026-11-10t07:32:11Z', 'null', 'true', '1731224000000', '2026-11-10T07:32:11.123+01:00', '2026-11-10 07:32:11z', '2026-11-10t07:32',
    '2026Z', '2026-11Z', '2026-11-10z', '2026-00', '2026-13', '2026-11-10T07:32:11.5z', '2026-11-10T07:32:11+01:00Z', '2026z',
    '2026-03-08T02:00:00Z', '2026-03-08T12:00:00', '2026-03-07T23:59:59', '2026-11-01T12:00:00', '2026-10-31 23:59:59', '2026-11-10T24:00:00',
];

// loose are forms Date.parse reads in ways the port does not follow. They
// are recorded to show what is left out; the Go tests do not replay them.
const loose = [
    '2026-11-10 07:32:11.5', '2026-11-10 07:32:11.123456', '2026-11-10 07:32:11 +0100', '2026-11-10 07:32:11+00',
    '2026-11-10 07:32:11.123456+00', 'Nov 10 2026 07:32:11 UTC', 'Tue, 10 Nov 2026 07:32:11 GMT', '11/10/2026', '2026/11/10',
    '2026-11-10 7:32', '10 November 2026', '0', '99', '02026', '20261', '2026-11T07:32Z', '2026-3', '2026-11-',
];

function parsed(text) {
    const ms = Date.parse(text);
    return Number.isNaN(ms) ? null : ms;
}

const values = [];
for (const json of ['null', 'true', 'false', '0', '1731224000000', '1731224000000.7', '-1', '8.64e15', '8.64e15', '8640000000000001',
    '1e300', '"2026-11-10T07:32:11Z"', '"2026-11-10 12:12:02"', '"soon"', '""', '[]', '["2026-11-10T07:32:11Z"]', '[1731224000000]',
    '[2026]', '{}', '{"a":1}', '["2026-11-10","x"]', '-8.64e15', '1.5', '-1.5']) {
    const value = JSON.parse(json);
    const ms = new Date(value).getTime();
    values.push({ json, ms: Number.isNaN(ms) ? null : ms });
}

const texts = [];
for (const json of ['1', '1.0', '1e21', '1e-7', '-0', '1.5e300', '1e999', '-1e999', 'true', 'null', '"x"', '""', '"a\\"b\\\\c"',
    '"line\\nbreak\\ttab\\u0000\\u001f\\u007f"', '"\\u2028\\u2029<>&"', '"\\u00e4\\ud83d\\ude00"', '[]', '{}', '[1,[2,{"b":1,"a":2}]]',
    '{"b":1,"a":2,"10":3,"9":4,"01":5,"a":6}', '{"x":{"y":[null,false,0.1]}}', '[ 1 , 2 ]', '{"k" : "v"}', '"\\/"', '123456789012345678901234567890',
    '0.000001', '0.0000001', '[1.10,2.0,3e2]', '{"__proto__":1,"constructor":2}']) {
    const out = JSON.stringify(JSON.parse(json));
    texts.push({ json, out, length: out.length });
}

const file = path.join(__dirname, '..', 'dates.json');
fs.writeFileSync(file, JSON.stringify({
    zone: process.env.TZ,
    supported: supported.map((text) => ({ text, ms: parsed(text) })),
    loose: loose.map((text) => ({ text, ms: parsed(text) })),
    values,
    texts,
}));
console.log(`wrote ${supported.length} supported and ${loose.length} loose texts, ${values.length} values and ${texts.length} JSON texts to ${file}`);
